import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { useMoods, useThoughts } from '../hooks/useStorage';

const MOOD_HUE = { 1:0, 2:20, 3:45, 4:160, 5:200 };
const MOOD_LABEL = { 1:'Väldigt dåligt', 2:'Dåligt', 3:'Okej', 4:'Bra', 5:'Väldigt bra' };

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const [expanded, setExpanded]    = useState(null);
  const isEmpty = moods.length === 0 && thoughts.length === 0;
  const maxTrap = Math.max(...Object.values(trapCounts), 1);
  const avgEmoji = ['','😔','😟','😐','🙂','😄'];

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 24px', position:'relative', overflow:'hidden' }}>
      <div style={{ position:'absolute', top:'50%', left:'50%', transform:'translate(-50%,-60%)', zIndex:0, opacity:0.6 }}>
        <MeshSphere size={300} speed={0.3} distort={0.35} hue1={195} hue2={215} />
      </div>
      <div style={{ position:'relative', zIndex:2, textAlign:'center' }}>
        <h2 style={{ fontFamily:'DM Serif Display,serif', fontSize:30, fontWeight:400, fontStyle:'italic', color:'rgba(240,235,227,0.82)', marginBottom:10 }}>Ingenting här än</h2>
        <p style={{ fontSize:14, color:'rgba(240,235,227,0.38)', marginBottom:32, fontWeight:300 }}>Börja med en tanke eller check-in.</p>
        <div style={{ display:'flex', gap:8, justifyContent:'center' }}>
          <button onClick={()=>setPage('home')} style={{ padding:'12px 22px', borderRadius:100, background:'rgba(240,235,227,0.88)', color:'#120e0a', fontSize:13, fontWeight:600, border:'none' }}>Analysera</button>
          <button onClick={()=>setPage('checkin')} style={{ padding:'12px 22px', borderRadius:100, background:'rgba(255,255,255,0.06)', border:'1px solid rgba(255,255,255,0.08)', color:'rgba(240,235,227,0.5)', fontSize:13 }}>Check-in</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', background:'#120e0a', paddingBottom:96, position:'relative' }}>

      {/* Small orb in corner — ambient light */}
      <div style={{ position:'fixed', top:'-15%', right:'-15%', zIndex:0, opacity:0.35, pointerEvents:'none' }}>
        <MeshSphere size={320} speed={0.2} distort={0.3} hue1={195} hue2={215} />
      </div>

      <div style={{ position:'relative', zIndex:1, padding:'32px 22px 0', animation:'fadeUp .7s both' }}>

        {/* Editorial header */}
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(240,235,227,0.28)', marginBottom:10 }}>Historik</p>
        <h1 style={{ fontFamily:'DM Serif Display,serif', fontSize:'clamp(32px,9vw,52px)', fontWeight:400, fontStyle:'italic', lineHeight:1.05, color:'rgba(240,235,227,0.88)', marginBottom:6 }}>
          {thoughts.length} tankar<br/>
          <span style={{ fontSize:'0.65em', color:'rgba(240,235,227,0.3)' }}>{streak > 0 ? `${streak} dagar i rad` : 'ingen streak ännu'}</span>
        </h1>

        <div style={{ height:1, background:'rgba(255,255,255,0.07)', margin:'20px 0' }} />

        {/* Mood constellation — unique visualization */}
        {moods.length > 0 && (
          <div style={{ marginBottom:24 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(240,235,227,0.28)', marginBottom:14 }}>Humörgraf</p>
            <div style={{ display:'flex', alignItems:'flex-end', gap:4, height:56, marginBottom:6 }}>
              {[...moods].reverse().map((m, i) => {
                const h = MOOD_HUE[m.score];
                const heightPct = (m.score / 5) * 100;
                return (
                  <div key={i} style={{ flex:1, height:'100%', display:'flex', flexDirection:'column', justifyContent:'flex-end', alignItems:'center', gap:3 }}>
                    <div style={{ width:'100%', borderRadius:'3px 3px 0 0', height:`${heightPct}%`, minHeight:3, background:`hsla(${h}, 60%, 55%, 0.7)`, boxShadow:`0 0 12px hsla(${h}, 70%, 55%, 0.25)` }} />
                    <span style={{ fontFamily:'DM Mono,monospace', fontSize:6, color:'rgba(240,235,227,0.2)', whiteSpace:'nowrap' }}>
                      {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Stats row */}
        <div style={{ display:'flex', gap:8, marginBottom:24, flexWrap:'wrap' }}>
          {[
            { val: avgMood>0?`${avgEmoji[Math.round(avgMood)]} ${avgMood}`:'—', label:'Snitt' },
            { val: thoughts.length, label:'Analyser' },
            { val: streak>0?`${streak}d`:'—', label:'Streak' },
          ].map(({ val, label }) => (
            <div key={label} style={{ padding:'9px 16px', background:'rgba(255,255,255,0.05)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:100, backdropFilter:'blur(8px)' }}>
              <span style={{ fontSize:13, fontWeight:600, color:'rgba(240,235,227,0.8)' }}>{val}</span>
              <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(240,235,227,0.3)', marginLeft:6, letterSpacing:'0.08em' }}>{label}</span>
            </div>
          ))}
        </div>

        {/* Trap freq */}
        {Object.keys(trapCounts).length > 0 && (
          <>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(240,235,227,0.28)', marginBottom:12 }}>Tankefällor</p>
            <div style={{ display:'flex', flexDirection:'column', gap:7, marginBottom:24 }}>
              {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([label,count]) => (
                <div key={label} style={{ display:'flex', alignItems:'center', gap:10 }}>
                  <span style={{ fontSize:12, color:'rgba(240,235,227,0.45)', flex:1, fontWeight:300 }}>{label}</span>
                  <div style={{ width:72, height:2, background:'rgba(255,255,255,0.07)', borderRadius:1, flexShrink:0 }}>
                    <div style={{ height:'100%', borderRadius:1, background:'rgba(240,235,227,0.3)', width:`${(count/maxTrap)*100}%`, boxShadow:'0 0 6px rgba(240,235,227,0.1)' }} />
                  </div>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(240,235,227,0.25)', width:14, textAlign:'right' }}>{count}</span>
                </div>
              ))}
            </div>
          </>
        )}

        {/* Thought log — expandable */}
        {thoughts.length > 0 && (
          <>
            <div style={{ height:1, background:'rgba(255,255,255,0.07)', marginBottom:16 }} />
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(240,235,227,0.28)', marginBottom:12 }}>Tankelog</p>
            <div style={{ display:'flex', flexDirection:'column', gap:3 }}>
              {thoughts.map((th, i) => (
                <div key={th.id}>
                  <button onClick={() => setExpanded(expanded===i?null:i)}
                    style={{ width:'100%', textAlign:'left', padding:'12px 14px', background:expanded===i?'rgba(255,255,255,0.07)':'rgba(255,255,255,0.03)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:expanded===i?'14px 14px 0 0':14, transition:'all .2s', display:'flex', alignItems:'center', gap:10 }}>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:'flex', justifyContent:'space-between', marginBottom:3 }}>
                        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(240,235,227,0.4)', textTransform:'uppercase', letterSpacing:'0.08em' }}>
                          {th.trap_icon} {th.trap_label}
                        </span>
                        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(240,235,227,0.2)' }}>
                          {new Date(th.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                        </span>
                      </div>
                      <p style={{ fontSize:12, color:'rgba(240,235,227,0.32)', fontStyle:'italic', margin:0, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:expanded===i?'normal':'nowrap' }}>
                        "{th.user_text?.slice(0,80)}{th.user_text?.length>80&&expanded!==i?'...':''}"
                      </p>
                    </div>
                    <span style={{ fontSize:11, color:'rgba(240,235,227,0.2)', transform:expanded===i?'rotate(180deg)':'none', transition:'transform .25s', flexShrink:0 }}>↓</span>
                  </button>
                  {expanded === i && (
                    <div style={{ padding:'12px 14px', background:'rgba(255,255,255,0.05)', border:'1px solid rgba(255,255,255,0.07)', borderTop:'none', borderRadius:'0 0 14px 14px', animation:'fadeUp .25s both' }}>
                      <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(240,235,227,0.28)', marginBottom:7 }}>Omramning</p>
                      <p style={{ fontSize:13, color:'rgba(240,235,227,0.62)', lineHeight:1.75, fontWeight:300 }}>{th.reframe}</p>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
}
